require __DIR__.'/lib.php';require_login();try{global $selectedBrand,$selectedMain,$selectedSub;$selectedBrand=trim($_GET['brand']??'');$selectedMain=trim($_GET['main_category']??'');$selectedSub=trim($_GET['subcategory']??'');[$platform,$rows]=workflow_platform_rows($_GET);$path=tempnam(sys_get_temp_dir(),'platform-');try{report_write_xlsx($path,$platform.' Inventory',['Product','Product SKU / Alias','Quantity'],$rows,['Platform'=>$platform,'Generated'=>date(DATE_ATOM),'Search'=>$_GET['q']??'','Brand'=>$selectedBrand,'Main Category'=>$selectedMain,'Subcategory'=>$selectedSub,'Status'=>$_GET['status']??'']);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$platform.'_Inventory_'.date('Y-m-d').'.xlsx"');header('Cache-Control: private, no-store');readfile($path);}finally{if(is_file($path))unlink($path);}}catch(Throwable $ex){http_response_code(400);echo e(safe_error_message($ex));}
